  function reviewPaymentTransaction(id){const x=state.paymentTransactions.find(t=>t.id===id);if(!x)return;const pending=x.status==='Pending approval',failed=x.status==='Failed';showModal((pending?'Approve ':'Review ')+x.id,(pending?'No charge has been submitted yet.':'Processor and approval evidence for this transaction.'),`<div class="info-grid"><div class="info"><small>Customer</small><b>${x.customer}</b></div><div class="info"><small>Unit</small><b>${x.unit}</b></div><div class="info"><small>Invoice</small><b>${x.invoice}</b></div><div class="info"><small>Processor reference</small><b>${x.processor}</b></div><div class="info"><small>Scheduled charge</small><b>${x.scheduled}</b></div><div class="info"><small>Amount</small><b>${money(x.amount)}</b></div></div><div class="fm-health" style="margin-top:12px"><div class="fm-check"><i>✓</i><div><b>Invoice approved</b><small>Rent, protection plan, credits and approved fees reconcile to ${money(x.amount)}.</small></div></div><div class="fm-check"><i>✓</i><div><b>Customer payment authority</b><small>${x.method} is linked to the active agreement.</small></div></div><div class="fm-check ${failed?'warn':''}"><i>${failed?'!':'✓'}</i><div><b>${failed?'Payment failed':'No charge submitted'}</b><small>${failed?'Review decline reason and customer recovery options.':'Approval will queue this one transaction for its scheduled date.'}</small></div></div></div>${pending?'<label class="field" style="margin-top:12px"><span>Administrator approval note</span><textarea id="paymentApprovalNote" rows="3" placeholder="Optional review note"></textarea></label>':''}`,pending?'Approve this charge':failed?'Create recovery action':'Close',()=>{if(pending){x.status='Approved';x.approvedBy='Faisal Kamaludin';renderTransactions();notify(x.id+' approved and queued for '+x.scheduled)}else if(failed)notify('Recovery action opened for '+x.id)})}


  // ===================================================================
  // CMS data layer. Everything above is the owner's reference prototype
