  // ----- Finance overview (live read model) -----
  function periodRange(p){const now=new Date(),y=now.getFullYear(),m=now.getMonth(),d=now.getDate(),f=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`,D=(yy,mm,dd)=>new Date(yy,mm,dd);const dow=(now.getDay()+6)%7;switch(p){case'today':return[f(now),f(now),'Today · '+now.toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric'})];case'last7':return[f(D(y,m,d-6)),f(now),'Last 7 days'];case'lastweek':return[f(D(y,m,d-dow-7)),f(D(y,m,d-dow-1)),'Last calendar week'];case'lastmonth':return[f(D(y,m-1,1)),f(D(y,m,0)),D(y,m-1,1).toLocaleDateString('en-SG',{month:'long',year:'numeric'})];case'qtd':{const q=Math.floor(m/3)*3;return[f(D(y,q,1)),f(now),`Q${q/3+1} ${y} to date`]}case'ytd':return[f(D(y,0,1)),f(now),`${y} year to date`];case'custom':return[state.customFrom||f(D(y,m,1)),state.customTo||f(now),`Custom period · ${state.customFrom||f(D(y,m,1))} – ${state.customTo||f(now)}`];default:return[f(D(y,m,1)),f(now),now.toLocaleDateString('en-SG',{month:'long',year:'numeric'})+' month to date']}}
  function overviewQuery(){const [from,to]=periodRange(state.financePeriod),q=new URLSearchParams({basis:state.financeBasis});if(state.financeFacility)q.set('branchId',state.financeFacility);q.set('from',from);q.set('to',to);return q.toString()}
