  // ----- Transactions & approvals (live register) -----
  const TX_LABEL={PENDING_APPROVAL:'Pending approval',DRAFT:'Draft',APPROVED:'Approved',QUEUED:'Approved',SUBMITTED:'Processing',SUCCEEDED:'Paid',FAILED:'Failed',CANCELLED:'Cancelled',EXPIRED:'Expired'};
  async function loadTransactions(){try{srv.transactions=await get('/finance/transactions');srv.txError=null}catch(e){srv.transactions=[];srv.txError=describeError(e)}}
  function transactionStatusClass(s){return s==='Paid'||s==='Approved'?'green':s==='Failed'?'red':s==='Cancelled'||s==='Expired'?'grey':'amber'}
  function renderTransactions(){
    const panel=finMount('bill-transactions');if(!panel)return;
    if(!srv.transactions){panel.innerHTML='<div class="card"><div class="card-body"><div class="section-empty">Loading payment register…</div></div></div>';loadTransactions().then(()=>{if(isActive('bill-transactions'))renderTransactions()});return}
    const status=state.transactionStatus||'all',all=srv.transactions.map(x=>({...x,label:TX_LABEL[x.status]||x.status})),rows=all.filter(x=>status==='all'||x.label===status),pending=all.filter(x=>x.status==='PENDING_APPROVAL'),failed=all.filter(x=>x.status==='FAILED'),paid=all.filter(x=>x.status==='SUCCEEDED'),approved=all.filter(x=>x.status==='APPROVED'||x.status==='QUEUED');
    const next=new Date();next.setMonth(next.getMonth()+1,1);
    panel.innerHTML=`<div class="fm-filter-bar"><label class="fm-select-wrap"><small>Status</small><select class="fm-select" data-transaction-status><option value="all">All statuses</option>${['Pending approval','Approved','Processing','Paid','Failed','Cancelled'].map(x=>`<option ${status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="fm-select-wrap"><small>Processor</small><select class="fm-select"><option>All payment methods</option><option>Stripe cards</option><option>Bank transfer</option><option>PayNow</option></select></label><span class="spacer"></span><button class="btn" data-fm-action="refund-calculator">＋ Calculate refund</button><button class="primary" data-fm-action="transaction-export">Export transactions</button></div>${srv.txError?`<div class="fm-note" style="margin-bottom:12px"><b>Register unavailable:</b> ${escapeHtml(srv.txError)}</div>`:''}<div class="fm-start fm-payment-control"><div><b>Manual approval is active</b><span>Monthly invoices are prepared for the 1st, but no saved payment method is charged until an administrator approves that specific transaction. There is deliberately no bulk-approve button.</span></div><span class="pill amber">Admin approval required</span></div><div class="fm-kpis"><div class="fm-kpi"><small>${tip('Awaiting approval','Draft payment instructions generated from issued invoices. They have not been submitted for charge.')}</small><strong>${pending.length}</strong><span>${money(sum(pending.map(x=>x.amount)))} scheduled</span></div><div class="fm-kpi"><small>${tip('Approved for charge','Individually reviewed instructions authorised by an administrator and queued.')}</small><strong>${approved.length}</strong><span>Queued individually</span></div><div class="fm-kpi"><small>${tip('Successful payments','Processor-confirmed charges allocated to invoices.')}</small><strong>${paid.length}</strong><span>Allocated to invoices</span></div><div class="fm-kpi"><small>${tip('Failed payments','Processor attempts that were declined, expired or otherwise not completed.')}</small><strong>${failed.length}</strong><span>${money(sum(failed.map(x=>x.amount)))} outstanding</span></div><div class="fm-kpi"><small>${tip('Refunds pending','Administrator-only refund cases waiting for review or processing.')}</small><strong>${srv.overview?.snapshot?.refundsPending?.value!=null?money(srv.overview.snapshot.refundsPending.value):'—'}</strong><span>See Credits &amp; refunds</span></div><div class="fm-kpi"><small>${tip('Next billing run','Invoices and draft payment instructions are generated for the first day of each month.')}</small><strong>${next.toLocaleDateString('en-SG',{day:'numeric',month:'short'})}</strong><span>Draft first, charge after approval</span></div></div><div class="card fm-transaction-card"><div class="card-head"><div><h3>Payment transaction register</h3><small style="color:var(--muted)">Internal transaction ID, Stripe/payment-processor reference, invoice, approval and result</small></div><button class="btn" data-fm-action="payment-policy">Payment control policy</button></div><div class="table-wrap"><table class="fm-table fm-transaction-table"><thead><tr><th>Transaction ID</th><th>Processor reference</th><th>Scheduled</th><th>Customer / unit</th><th>Invoice</th><th>Method</th><th>Amount</th><th>Status</th><th>Approved by</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${escapeHtml(x.id.slice(-10).toUpperCase())}</b></td><td>${escapeHtml(x.paymentIntentId||'—')}</td><td>${new Date(x.createdAt).toLocaleDateString('en-SG',{day:'2-digit',month:'short',year:'numeric'})}</td><td>${escapeHtml(x.tenant)}<small class="fm-capped">${escapeHtml(x.unit)}</small></td><td>${escapeHtml(x.invoiceNo)}</td><td>${escapeHtml(x.method||'Saved card')}</td><td><b>${money(x.amount)}</b></td><td><span class="pill ${transactionStatusClass(x.label)}">${x.label}</span>${x.attempts?`<small class="fm-capped">${x.attempts} attempt${x.attempts===1?'':'s'}</small>`:''}</td><td>${escapeHtml(x.approvedBy||'—')}</td><td><button class="btn" data-fm-action="transaction-review" data-transaction-id="${escapeHtml(x.id)}">${x.status==='PENDING_APPROVAL'?'Review & approve':'View'}</button></td></tr>`).join('')||'<tr><td colspan="10" style="text-align:center">No transactions match this filter. Issue invoices to create payment instructions.</td></tr>'}</tbody></table></div></div><div class="fm-data-lineage"><div><b>Invoice source</b><span>Customer agreement, monthly rent, protection plan, credits and approved fees.</span></div><div><b>Payment source</b><span>Stripe PaymentIntent/Charge, PayNow or bank receipt and reconciliation result.</span></div><div><b>Approval evidence</b><span>Administrator, timestamp, decision, exception reason and audit entry.</span></div></div>`;
    panel.querySelector('[data-transaction-status]')?.addEventListener('change',e=>{state.transactionStatus=e.target.value;renderTransactions()});
  }
  function exportTransactions(){const rows=srv.transactions||[];downloadCsv('StoreLah_Payment_Transactions.csv',[['Transaction ID','Processor reference','Invoice','Customer','Unit','Created','Amount','Status','Payment method','Approved by','Attempts'],...rows.map(x=>[x.id,x.paymentIntentId||'',x.invoiceNo,x.tenant,x.unit,x.createdAt,x.amount,TX_LABEL[x.status]||x.status,x.method||'',x.approvedBy||'',x.attempts])]);notify('Payment transaction register downloaded')}
  function reviewPaymentTransaction(id){const x=(srv.transactions||[]).find(t=>t.id===id);if(!x)return;const pending=x.status==='PENDING_APPROVAL',failed=x.status==='FAILED',canApprove=can('bill-transactions:approve');showModal((pending?'Approve ':'Review ')+x.id.slice(-10).toUpperCase(),pending?'No charge has been submitted yet.':'Processor and approval evidence for this transaction.',`<div class="info-grid"><div class="info"><small>Customer</small><b>${escapeHtml(x.tenant)}</b></div><div class="info"><small>Unit</small><b>${escapeHtml(x.unit)}</b></div><div class="info"><small>Invoice</small><b>${escapeHtml(x.invoiceNo)}</b></div><div class="info"><small>Processor reference</small><b>${escapeHtml(x.paymentIntentId||'Not submitted')}</b></div><div class="info"><small>Facility</small><b>${escapeHtml(x.branch||'—')}</b></div><div class="info"><small>Amount</small><b>${money(x.amount)}</b></div></div><div class="fm-health" style="margin-top:12px"><div class="fm-check"><i>✓</i><div><b>Invoice issued</b><small>The server re-checks the invoice balance and version when you approve.</small></div></div><div class="fm-check"><i>✓</i><div><b>Customer payment authority</b><small>${escapeHtml(x.method||'Saved card')} on the tenant’s agreement; card details are never shown here.</small></div></div><div class="fm-check ${failed?'warn':''}"><i>${failed?'!':'✓'}</i><div><b>${failed?'Payment failed':pending?'No charge submitted':escapeHtml(TX_LABEL[x.status]||x.status)}</b><small>${failed?escapeHtml(x.failureReason||'Review decline reason and recovery options.'):pending?'Approval queues this one transaction; nothing is charged in bulk.':'Approved by '+escapeHtml(x.approvedBy||'—')+(x.approvedAt?' · '+new Date(x.approvedAt).toLocaleString('en-SG'):'')}</small></div></div></div>${pending&&!canApprove?'<div class="fm-note" style="margin-top:12px">You can view this instruction but approving a charge needs the Transactions approve permission.</div>':''}`,pending&&canApprove?'Approve this charge':failed?'Open arrears':'',async()=>{if(pending){try{await post(`/finance/transactions/${x.id}/approve`,{version:x.version});await loadTransactions();renderTransactions();notify(x.invoiceNo+' charge approved and queued')}catch(err){notify(describeError(err))}}else if(failed)showPanel('bill-arrears')})}

  // ----- Refund & final-charge calculator (server calculation + refund case) -----
  async function openRefundCalculator(){let invoices=[];try{const r=await get('/finance/invoices');invoices=(r.items||r||[]).filter(x=>x.tenantId)}catch{}const opts=invoices.slice(0,300).map(x=>`<option value="${escapeHtml(x.tenantId)}|${escapeHtml(x.id)}" data-rent="${Number(x.total??x.amount??0)}">${escapeHtml(x.tenant)} · ${escapeHtml(x.no||x.invoiceNo)} · ${escapeHtml(x.unit||'')}</option>`).join('');
    showModal('Refund & final-charge calculator','Administrator-only · unused storage is prorated automatically; deductions and overrides require a reason.',`<div class="fm-refund-layout"><div class="form-grid"><label class="field"><span>Customer / invoice</span><select id="refundCustomer">${opts||'<option value="">No invoices found</option>'}</select></label><label class="field"><span>Move-out date</span><input type="date" id="refundMoveOut" value="${new Date().toISOString().slice(0,10)}"></label><label class="field"><span>Monthly storage rent</span><input id="refundMonthlyRent" type="number" value="${invoices[0]?Number(invoices[0].total??invoices[0].amount??0):0}"></label><label class="field"><span>Days in billing month</span><input id="refundMonthDays" type="number" value="30"></label><label class="field"><span>Unused storage days</span><input id="refundUnusedDays" type="number" value="0"></label><label class="field"><span>Other refundable credit</span><input id="refundCredit" type="number" value="0"></label><label class="field"><span>Early-termination penalty</span><input id="refundEarlyFee" type="number" value="0"></label><label class="field"><span>Damage / miscellaneous charge</span><input id="refundDamageFee" type="number" value="0"></label><label class="field full"><span>Final amount override · optional</span><input id="refundOverride" type="number" placeholder="Leave blank to use calculated amount"></label><label class="field full"><span>Override / deduction reason</span><textarea id="refundReason" rows="3" placeholder="Required for an override, early-termination penalty, damage or miscellaneous charge"></textarea></label></div><aside class="fm-refund-summary"><small>Prorated storage refund</small><b id="refundStorageCalc">$0</b><span>Monthly rent ÷ days × unused days</span><small id="refundOutcomeLabel">Refund to customer</small><strong id="refundFinalCalc">$0</strong><span>Refunds are not processed until an approver confirms. A negative result becomes an additional customer charge for approval.</span></aside></div><div class="fm-note" id="refundReasonError" style="display:none;margin-top:12px;color:var(--red)">Add a reason for the deduction or override before continuing.</div>`,can('bill-credits:create')?'Submit for approval':'',()=>{const calc=updateRefundCalculator(),reason=document.getElementById('refundReason')?.value.trim(),[tenantId,invoiceId]=(document.getElementById('refundCustomer')?.value||'').split('|');if(calc.needsReason&&!reason){document.getElementById('refundReasonError').style.display='block';return false}if(!tenantId){notify('Choose a customer invoice first.');return false}const n=id=>Number(document.getElementById(id)?.value)||0,ov=document.getElementById('refundOverride')?.value;post('/finance/refunds',{tenantId,invoiceId,monthlyRent:n('refundMonthlyRent'),daysInMonth:Math.max(1,n('refundMonthDays')),unusedDays:n('refundUnusedDays'),refundableCredit:n('refundCredit'),earlyTerminationFee:n('refundEarlyFee'),damageCharge:n('refundDamageFee'),...(ov!==''&&ov!=null?{override:Number(ov)}:{}),...(reason?{reason}:{})}).then(()=>notify(calc.final<0?money(Math.abs(calc.final))+' additional charge created as a draft for approval':money(calc.final)+' refund submitted for approval')).catch(e=>notify(describeError(e)))});
    document.getElementById('refundCustomer')?.addEventListener('change',e=>{const r=e.target.selectedOptions[0]?.dataset.rent;if(r!=null){document.getElementById('refundMonthlyRent').value=r;updateRefundCalculator()}});
    document.querySelectorAll('#fmModalBody input').forEach(i=>i.addEventListener('input',updateRefundCalculator));updateRefundCalculator()}

  // ----- Budgets & expenses: ledger lines are server records -----
  const EXP_LABEL={PAID:'Paid',COMMITTED:'Committed',DRAFT:'Draft'},EXP_CODE={Paid:'PAID',Committed:'COMMITTED',Draft:'DRAFT'};
  async function loadExpenses(){try{const rows=await get(`/finance/expenses?branchId=${encodeURIComponent(srv.branchId)}`);srv.expenses=rows;state.expenses=rows.map(x=>({id:x.receiptRef||('EXP-'+x.id.slice(-5).toUpperCase()),_id:x.id,month:String(x.incurredAt).slice(0,7),date:String(x.incurredAt).slice(0,10),vendor:x.vendor||'—',description:x.description||'—',category:x.category,amount:x.amount,status:EXP_LABEL[x.status]||'Paid',note:x.note||'',ref:x.receiptRef||''}))}catch(e){srv.expenses=[];state.expenses=[];notify(describeError(e))}}
  function expenseForm(x){const cats=state.opex.map(c=>`<option ${x&&x.category===c.name?'selected':''}>${escapeHtml(c.name)}</option>`).join('');return `<div class="form-grid"><label class="field"><span>Date *</span><input type="date" id="fmExpDate" value="${x?x.date:state.budgetMonth+'-01'}"></label><label class="field"><span>Reference</span><input id="fmExpRef" value="${escapeHtml(x?.ref||'')}" placeholder="Invoice / receipt / PO"></label><label class="field"><span>Vendor</span><input id="fmExpVendor" value="${escapeHtml(x&&x.vendor!=='—'?x.vendor:'')}"></label><label class="field"><span>Category *</span><select id="fmExpCat">${cats}</select></label><label class="field full"><span>Description</span><input id="fmExpDesc" value="${escapeHtml(x&&x.description!=='—'?x.description:'')}"></label><label class="field"><span>Amount *</span><input type="number" min="0" step="0.01" id="fmExpAmt" value="${x?x.amount:''}"></label><label class="field"><span>Status</span><select id="fmExpStatus">${['Draft','Committed','Paid'].map(s=>`<option ${x&&x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field full"><span>Note</span><textarea id="fmExpNote" rows="2">${escapeHtml(x?.note||'')}</textarea></label></div>`}
  function expensePayload(){const v=id=>document.getElementById(id)?.value??'';return {incurredAt:v('fmExpDate'),category:v('fmExpCat'),amount:Number(v('fmExpAmt')),vendor:v('fmExpVendor')||undefined,receiptRef:v('fmExpRef')||undefined,description:v('fmExpDesc')||undefined,status:EXP_CODE[v('fmExpStatus')]||'PAID',note:v('fmExpNote')||undefined}}

  function isActive(id){return !!document.getElementById(id)?.classList.contains('active')}

