  document.addEventListener('change',e=>{const m=e.target.closest('[data-fm-select="model"]');if(m&&billing.contains(m)&&m.value==='blank'){e.stopImmediatePropagation();m.value=srv.model?'draft:'+srv.model.id:'';document.querySelector('#billing [data-fm-action="new-model"]')||null;const fake=document.createElement('button');fake.dataset.fmAction='new-model';billing.appendChild(fake);fake.click();fake.remove();return}},true);
